//! Clipboard fallback with snapshot/restore guarded by `changeCount`, so content the user
//! copies after us is never overwritten. Dictated text is marked with the nspasteboard.org
//! transient/concealed/auto-generated types so well-behaved clipboard managers skip it.
//!
//! Snapshots stay inside the addon; clipboard contents are never handed to JavaScript except by
//! `clipboard_read_text`, which exists only so tests can verify writes.

use napi_derive::napi;
use objc2::rc::Retained;
use objc2::runtime::ProtocolObject;
use objc2_app_kit::{NSPasteboard, NSPasteboardItem, NSPasteboardTypeString, NSPasteboardWriting};
use objc2_foundation::{NSArray, NSData, NSString};
use std::collections::HashMap;
use std::sync::Mutex;

pub const TRANSIENT_TYPES: [&str; 3] = [
    "org.nspasteboard.TransientType",
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.AutoGeneratedType",
];

type ItemData = Vec<(String, Vec<u8>)>;

/// What was on the clipboard. `items` is empty for a snapshot that must not be written back.
struct Snapshot {
    items: Vec<ItemData>,
    /// More data than `MAX_SNAPSHOT_BYTES`: copying all of it would stall the main thread and
    /// a partial copy would lose part of what the person had, so it is never restored.
    too_large: bool,
}

static SNAPSHOTS: Mutex<Option<(u32, HashMap<u32, Snapshot>)>> = Mutex::new(None);

const MAX_SNAPSHOT_BYTES: usize = 32 * 1024 * 1024;

fn is_sensitive(ty: &str) -> bool {
    TRANSIENT_TYPES.contains(&ty)
}

/// changeCount right after the addon's own latest clipboard write. Murmur marks its copy-only
/// results transient too, so those must still be kept and restored, unlike a password manager's.
static OWN_WRITE_COUNT: Mutex<Option<f64>> = Mutex::new(None);

fn remember_own_write(count: f64) {
    *OWN_WRITE_COUNT.lock().unwrap() = Some(count);
}

/// A snapshot is refused only for marked content that Murmur did not write itself.
fn refuses_snapshot(has_sensitive_type: bool, current_count: f64, own_write_count: Option<f64>) -> bool {
    has_sensitive_type && own_write_count != Some(current_count)
}

fn pasteboard() -> Retained<NSPasteboard> {
    NSPasteboard::generalPasteboard()
}

#[napi]
pub fn clipboard_change_count() -> f64 {
    pasteboard().changeCount() as f64
}

/// Copies every item and type on the clipboard into addon memory. Returns a snapshot id.
#[napi]
pub fn clipboard_snapshot() -> u32 {
    let snapshot = objc2::rc::autoreleasepool(|_| {
        let pb = pasteboard();
        let empty = Snapshot {
            items: Vec::new(),
            too_large: false,
        };
        let Some(items) = pb.pasteboardItems() else {
            return empty;
        };
        // A password manager's copy (concealed, transient or auto-generated) is neither read
        // nor kept: writing it back would give it a new changeCount, so the manager's timed
        // clear would never remove it. Restoring then leaves the clipboard empty instead.
        let marked = items
            .iter()
            .any(|item| item.types().iter().any(|ty| is_sensitive(&ty.to_string())));
        let own = *OWN_WRITE_COUNT.lock().unwrap();
        if refuses_snapshot(marked, pb.changeCount() as f64, own) {
            return empty;
        }
        let mut total = 0usize;
        let mut copied = Vec::new();
        for item in items.iter() {
            let mut data = ItemData::new();
            for ty in item.types().iter() {
                let name = ty.to_string();
                // dyn.* types are derived from the real ones; rendering them gains nothing.
                if name.starts_with("dyn.") {
                    continue;
                }
                if let Some(d) = item.dataForType(&ty) {
                    total += d.len();
                    if total > MAX_SNAPSHOT_BYTES {
                        return Snapshot {
                            items: Vec::new(),
                            too_large: true,
                        };
                    }
                    data.push((name, d.to_vec()));
                }
            }
            copied.push(data);
        }
        Snapshot {
            items: copied,
            too_large: false,
        }
    });
    let mut guard = SNAPSHOTS.lock().unwrap();
    let (next, map) = guard.get_or_insert_with(|| (1, HashMap::new()));
    let id = *next;
    *next += 1;
    map.insert(id, snapshot);
    id
}

#[napi]
pub fn clipboard_discard_snapshot(id: u32) -> bool {
    SNAPSHOTS
        .lock()
        .unwrap()
        .as_mut()
        .is_some_and(|(_, m)| m.remove(&id).is_some())
}

fn write_items(items: &[ItemData]) -> bool {
    objc2::rc::autoreleasepool(|_| {
        let pb = pasteboard();
        pb.clearContents();
        if items.is_empty() {
            return true;
        }
        let objects: Vec<Retained<ProtocolObject<dyn NSPasteboardWriting>>> = items
            .iter()
            .map(|types| {
                let item = NSPasteboardItem::new();
                for (ty, bytes) in types {
                    item.setData_forType(&NSData::with_bytes(bytes), &NSString::from_str(ty));
                }
                ProtocolObject::from_retained(item)
            })
            .collect();
        pb.writeObjects(&NSArray::from_retained_slice(&objects))
    })
}

/// Writes plain text and returns the resulting changeCount, which the caller must keep to
/// decide later whether restoring is safe. `None` when macOS refused the write.
pub fn write_text(text: &str, transient: bool) -> Option<f64> {
    let string_type = unsafe { NSPasteboardTypeString }.to_string();
    let mut types = vec![(string_type, text.as_bytes().to_vec())];
    if transient {
        types.extend(TRANSIENT_TYPES.iter().map(|t| (t.to_string(), Vec::new())));
    }
    let count = write_items(&[types]).then(clipboard_change_count)?;
    remember_own_write(count);
    Some(count)
}

#[napi]
pub fn clipboard_write_text(text: String, transient: Option<bool>) -> f64 {
    write_text(&text, transient.unwrap_or(true)).unwrap_or_else(clipboard_change_count)
}

/// True when the clipboard's newest content is marked concealed, transient or auto-generated
/// (a password manager's copy): such content is never read.
pub fn pasteboard_has_sensitive_type() -> bool {
    objc2::rc::autoreleasepool(|_| {
        pasteboard().types().is_some_and(|t| {
            t.iter().any(|ty| is_sensitive(&ty.to_string()))
        })
    })
}

pub fn read_plain_text() -> Option<String> {
    objc2::rc::autoreleasepool(|_| {
        pasteboard()
            .stringForType(unsafe { NSPasteboardTypeString })
            .map(|s| s.to_string())
    })
}

#[napi]
pub fn clipboard_read_text() -> Option<String> {
    objc2::rc::autoreleasepool(|_| {
        pasteboard()
            .stringForType(unsafe { NSPasteboardTypeString })
            .map(|s| s.to_string())
    })
}

#[napi]
pub fn clipboard_types() -> Vec<String> {
    objc2::rc::autoreleasepool(|_| {
        pasteboard()
            .types()
            .map(|t| t.iter().map(|s| s.to_string()).collect())
            .unwrap_or_default()
    })
}

#[napi(object)]
pub struct RestoreResult {
    pub restored: bool,
    /// "restored" | "clipboard-changed-since-write" | "unknown-snapshot" | "snapshot-too-large"
    pub reason: String,
}

/// Restores a snapshot only if nobody has written to the clipboard since `expected_change_count`.
#[napi]
pub fn clipboard_restore(id: u32, expected_change_count: f64) -> RestoreResult {
    let snapshot = SNAPSHOTS
        .lock()
        .unwrap()
        .as_mut()
        .and_then(|(_, m)| m.remove(&id));
    let Some(snapshot) = snapshot else {
        return RestoreResult {
            restored: false,
            reason: "unknown-snapshot".into(),
        };
    };
    if clipboard_change_count() != expected_change_count {
        return RestoreResult {
            restored: false,
            reason: "clipboard-changed-since-write".into(),
        };
    }
    if snapshot.too_large {
        return RestoreResult {
            restored: false,
            reason: "snapshot-too-large".into(),
        };
    }
    if write_items(&snapshot.items) {
        remember_own_write(clipboard_change_count());
    }
    RestoreResult {
        restored: true,
        reason: "restored".into(),
    }
}

#[cfg(test)]
mod tests {
    use super::refuses_snapshot;

    #[test]
    fn password_manager_content_is_refused() {
        assert!(refuses_snapshot(true, 10.0, None));
        assert!(refuses_snapshot(true, 10.0, Some(9.0)));
    }

    #[test]
    fn our_own_marked_write_is_kept() {
        assert!(!refuses_snapshot(true, 10.0, Some(10.0)));
    }

    #[test]
    fn unmarked_content_is_always_kept() {
        assert!(!refuses_snapshot(false, 10.0, None));
        assert!(!refuses_snapshot(false, 10.0, Some(3.0)));
    }
}
